from itertools import islice


def agrupar(iterable, n):
    """Genera listas de n elementos seguidos (la última puede ser más corta)."""
    it = iter(iterable)
    while True:
        grupo = list(islice(it, n))
        if not grupo:
            return
        yield grupo

