from itertools import islice


def chunks(iterable, n):
    """Generates lists of n items in a row (the last one may be shorter)."""
    it = iter(iterable)
    while True:
        group = list(islice(it, n))
        if not group:
            return
        yield group

es.lecturas.py:
"""Leer el registro de lecturas."""


def leer_registro(lineas):
    """Genera (libro, capitulo) por cada línea «Libro;capítulo»; salta vacías y comentarios."""
    for linea in lineas:
        linea = linea.strip()
        if not linea or linea.startswith("#"):
            continue
        libro, capitulo = linea.split(";")
        yield libro, int(capitulo)

