def read_log(lines):
    """Generates (book, chapter) for each "Book;chapter" line; skips empty lines and comments."""
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        book, chapter = line.split(";")
        yield book, int(chapter)

