            raise PlanInvalidoError("Lee al menos un capítulo por día")
        for libro in libros:
            if libro not in biblia.CAPITULOS:
                raise PlanInvalidoError(f"No conozco el libro {libro}")
        self.libros = list(libros)
        self.por_dia = por_dia

    def capitulos(self):
        for libro in self.libros:
            for numero in range(1, biblia.CAPITULOS[libro] + 1):
                yield f"{libro} {numero}"

    def dias(self):
        yield from enumerate(agrupar(self.capitulos(), self.por_dia), start=1)

    def total(self):
        return sum(biblia.CAPITULOS[libro] for libro in self.libros)


