    def __init__(self, books, per_day):
        if per_day < 1:
            raise InvalidPlanError("Read at least one chapter a day")
        for book in books:
            bible.CHAPTERS[book]
        self.books = list(books)
        self.per_day = per_day

    def chapters(self):
        for book in self.books:
            for number in range(1, bible.CHAPTERS[book] + 1):
                yield f"{book} {number}"

    def days(self):
        yield from enumerate(chunks(self.chapters(), self.per_day), start=1)

    def total(self):
        return sum(bible.CHAPTERS[book] for book in self.books)


def test_plan():
    plan = ReadingPlan(["Ruth"], 3)
    assert list(plan.days()) == [(1, ["Ruth 1", "Ruth 2", "Ruth 3"]), (2, ["Ruth 4"])]
    assert plan.total() == 4
    assert list(ReadingPlan(["Obadiah"], 10).days()) == [(1, ["Obadiah 1"])]
    for books, per_day in [(["Ruth"], 0), (["Ruth"], 0)]:
        try:
            ReadingPlan(books, per_day)
        except InvalidPlanError:
            pass
        else:
            assert False, "the plan should have been invalid"


def main():
    test_plan()
    print("Tests: all good")
    plan = ReadingPlan(["Ruth", "Jonah", "Philippians"], 5)
    count = 0
    for day, reading in plan.days():
        print(f"Day {day}: {', '.join(reading)}")
        count = day
    print(f"Total: {plan.total()} chapters in {count} days")
    for books, per_day in [(["Ruth"], 0)]:
        try:
            ReadingPlan(books, per_day)
        except InvalidPlanError as error:
            print("Error:", error)


if __name__ == "__main__":
    main()
